targets.expr:
avg(
  avg_over_time(
    app_e2e_probe_success{
      env="$env",
      collection=~"$collection",
      probe!="asset_fetch"
    }[24h]
  )
) * 100

min by (env) (
  last_over_time(
    app_e2e_probe_success{
      env="$env",
      collection=~"$collection",
      probe!="asset_fetch"
    }[5h]
  )
)
